    /// <summary>
    /// Extend form init method to change control decimal digits
    /// </summary>
    public void init()
    {
        next init();

        this.metSetDecimalDisplay(this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_RetailDiscountLineOffer_discAmount)));
        this.metSetDecimalDisplay(this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscountLine_RetailDiscountLineOffer_discPct)));
        this.metSetDecimalDisplay(this.design().controlName(formControlStr(RetailPeriodicDiscount, RetailPeriodicDiscount_DiscountPercentValue)));
        this.metSetDecimalDisplay(this.design().controlName(formControlStr(RetailPeriodicDiscount, RBOMultibuyDiscountLine_priceDiscPct)));
    }

/// <summary>
/// Set the number of decimal digits to be set and displayed on the real edit (amount) controls
/// </summary>
/// <param name = "_control">Control on which decimal digits to be changed</param>
private void metSetDecimalDisplay(FormRealControl _control)
{
    if(_control != null)
    {
        _control.noOfDecimals(4, AutoMode::Fixed);
        _control.minNoOfDecimals(4, AutoMode::Fixed);
    }
}
